query:
UPDATE course_lessons SET content = REPLACE(content, 
  'At 480V with wet hands (1,000Ω body resistance), current through the body = 480/1000 = 0.48A = 480mA',
  'At 480V 3-phase with wet hands (1,000Ω body resistance), phase-to-ground voltage = 277V. Current through the body = 277/1000 = 0.277A = 277mA (phase-to-ground contact is the most common shock scenario; phase-to-phase contact at 480V would produce 480mA)'
) WHERE id = 60005;

